using System.Collections.Generic;
using UnityEngine;

namespace Game.Runtime.Pooling
{
    public class ObjectPool : MonoBehaviour
    {
        [SerializeField] private GameObject _prefab;
        [SerializeField] private int _initialSize = 4;
        [SerializeField] private Transform _parent;

        private Stack<GameObject> _pool;

        private void Awake()
        {
            Initialize(_prefab, _initialSize, _parent);
        }

        public void Initialize(GameObject prefab, int initialSize, Transform parent = null)
        {
            _prefab = prefab;
            _parent = parent;
            _pool = new Stack<GameObject>(Mathf.Max(initialSize, 0));

            if (_prefab == null)
            {
                Debug.LogError("ObjectPool: prefab is not assigned.", this);
                return;
            }

            for (int i = 0; i < initialSize; i++)
            {
                _pool.Push(CreateInstance());
            }
        }

        public GameObject Get()
        {
            if (_prefab == null)
            {
                Debug.LogError("ObjectPool: prefab is not assigned.", this);
                return null;
            }

            GameObject instance = _pool.Count > 0 ? _pool.Pop() : CreateInstance();
            instance.SetActive(true);
            return instance;
        }

        public void Release(GameObject instance)
        {
            if (instance == null)
            {
                return;
            }

            instance.SetActive(false);
            instance.transform.SetParent(_parent, false);
            _pool.Push(instance);
        }

        private GameObject CreateInstance()
        {
            GameObject instance = Instantiate(_prefab, _parent);
            instance.SetActive(false);
            return instance;
        }
    }
}
