using NUnit.Framework;
using UnityEngine;
using Game.Runtime.Pooling;

public class ObjectPoolTests
{
    [Test]
    public void Get_Reuses_Released_Instance_Instead_Of_Creating_New()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();
        var prefab = new GameObject("Prefab");
        pool.Initialize(prefab, 0);

        GameObject a = pool.Get();
        pool.Release(a);
        GameObject b = pool.Get();

        Assert.AreSame(a, b);

        Object.DestroyImmediate(a);
        Object.DestroyImmediate(prefab);
        Object.DestroyImmediate(poolGO);
    }

    [Test]
    public void Get_Grows_Pool_When_Empty()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();
        var prefab = new GameObject("Prefab");
        pool.Initialize(prefab, 1);

        GameObject a = pool.Get();
        GameObject b = pool.Get();

        Assert.AreNotSame(a, b);
        Assert.IsNotNull(b);

        Object.DestroyImmediate(a);
        Object.DestroyImmediate(b);
        Object.DestroyImmediate(prefab);
        Object.DestroyImmediate(poolGO);
    }

    [Test]
    public void Prewarm_Creates_Distinct_Initial_Instances()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();
        var prefab = new GameObject("Prefab");
        pool.Initialize(prefab, 3);

        GameObject a = pool.Get();
        GameObject b = pool.Get();
        GameObject c = pool.Get();

        Assert.AreNotSame(a, b);
        Assert.AreNotSame(b, c);
        Assert.AreNotSame(a, c);

        Object.DestroyImmediate(a);
        Object.DestroyImmediate(b);
        Object.DestroyImmediate(c);
        Object.DestroyImmediate(prefab);
        Object.DestroyImmediate(poolGO);
    }

    [Test]
    public void Get_Activates_Instance_And_Release_Deactivates_It()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();
        var prefab = new GameObject("Prefab");
        pool.Initialize(prefab, 1);

        GameObject a = pool.Get();
        Assert.IsTrue(a.activeSelf);

        pool.Release(a);
        Assert.IsFalse(a.activeSelf);

        Object.DestroyImmediate(a);
        Object.DestroyImmediate(prefab);
        Object.DestroyImmediate(poolGO);
    }

    [Test]
    public void Release_Null_Does_Not_Throw()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();
        var prefab = new GameObject("Prefab");
        pool.Initialize(prefab, 0);

        Assert.DoesNotThrow(() => pool.Release(null));

        Object.DestroyImmediate(prefab);
        Object.DestroyImmediate(poolGO);
    }

    [Test]
    public void Get_Without_Prefab_Returns_Null_And_Logs_Error()
    {
        var poolGO = new GameObject("Pool");
        var pool = poolGO.AddComponent<ObjectPool>();

        LogAssert.Expect(LogType.Error, new System.Text.RegularExpressions.Regex("prefab is not assigned"));
        GameObject result = pool.Get();

        Assert.IsNull(result);

        Object.DestroyImmediate(poolGO);
    }
}
